// 智能体开着且有批量执行权限时，菜单里才有批次审批页（APP_AGENT 关着时整组菜单隐藏）
const agentOn = computed(() => menu.routes.some((r) => r.name === 'agent-batch'))
const enriching = ref(false)

/** 确认后对选中的客户批量执行“补齐客户信息”，再打开批次审批页。 */
async function enrich() {
  const ids = selection.value.map((r) => r.id).slice(0, 200)
  try {
    await ElMessageBox.confirm(
      t('demo.customer.enrich.confirm', { count: ids.length, skill: DEMO_CUSTOMER_ENRICH_SKILL }),
      t('demo.customer.enrich.title'),
      {
        confirmButtonText: t('demo.customer.enrich.action'),
        cancelButtonText: t('common.action.cancel'),
      },
    )
  } catch {
    return
  }
  enriching.value = true
  try {
    const batch = await agentBatchApi.create({
      skill: DEMO_CUSTOMER_ENRICH_SKILL,
      target: DEMO_CUSTOMER_TARGET,
      ids,
    })
    await router.push({ name: 'agent-batch', query: { id: String(batch.id) } })
